rules.firestore_rules_text:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function getUserProfile() {
      return get(/databases/$(database)/documents/usuarios/$(request.auth.uid)).data;
    }

    match /igrejas/{igrejaId} {
      allow read: if true;
      allow create: if request.auth != null;
      allow update, delete: if request.auth != null && getUserProfile().igreja_id == igrejaId && getUserProfile().role == 'admin';
    }

    match /usuarios/{userId} {
      allow read: if request.auth != null;
      allow create, update: if request.auth != null && request.auth.uid == userId;
      allow delete: if false;
    }

    match /noticias/{noticiaId} {
      allow read: if request.auth != null && (resource == null || getUserProfile().igreja_id == resource.data.igreja_id);
      allow create: if request.auth != null && getUserProfile().role == 'admin' && request.resource.data.igreja_id == getUserProfile().igreja_id;
      allow update, delete: if request.auth != null && getUserProfile().role == 'admin' && resource.data.igreja_id == getUserProfile().igreja_id;
    }
  }
}
